body.t-vaporwave .bg-fx {
  background-image:
    linear-gradient(rgba(1,205,254,.14) 1px, transparent 1px),
    linear-gradient(90deg, rgba(1,205,254,.14) 1px, transparent 1px);
  background-size: 44px 44px;
  -webkit-mask-image: linear-gradient(180deg, transparent 30%, #000 78%);
  mask-image: linear-gradient(180deg, transparent 30%, #000 78%);
}
body.t-vaporwave .hero h1 { font-style: italic; text-transform: uppercase; letter-spacing: 2px; filter: drop-shadow(0 0 18px rgba(255,113,206,.4)); }
body.t-vaporwave .tagline { color: #fffb96; font-style: italic; letter-spacing: 2px; }
body.t-vaporwave .section-title { font-style: italic; text-transform: uppercase; }
body.t-vaporwave .section-tag { background: rgba(1,205,254,.1); }
body.t-vaporwave .card { border-color: rgba(255,113,206,.25); background: linear-gradient(160deg, rgba(255,113,206,.07), rgba(1,205,254,.05)); }
body.t-vaporwave .card:hover { border-color: var(--accent); box-shadow: 0 0 26px rgba(1,205,254,.22), 0 0 46px rgba(255,113,206,.14); }
body.t-vaporwave .card.featured { border-color: var(--accent-2); }
body.t-vaporwave .card.featured::before { background: linear-gradient(90deg, #ff71ce, #01cdfe); color: #150826; }
body.t-vaporwave .btn-primary { background: linear-gradient(90deg, #ff71ce, #b967ff); color: #fff; }
body.t-vaporwave .btn-primary:hover { box-shadow: 0 0 28px rgba(255,113,206,.45); }
body.t-vaporwave .btn-ghost:hover { box-shadow: 0 0 20px rgba(1,205,254,.25); }
body.t-vaporwave .bar-fill { background: linear-gradient(90deg, #01cdfe, #ff71ce); }
body.t-vaporwave .stat b { background: linear-gradient(180deg, #fffb96, #ff71ce); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
